/ Cấu hình auto_error / dòng 14","error_element":null,"noti_running_process":"Gửi email thất bại: [x]","noti_campaign":"Gửi email thất bại: [x]. Chiến dịch tạm dừng sau 5 lần lỗi liên tiếp.","update_status_account":null,"update_status_campaign":"tạm dừng","update_login_status":null,"disable_action_codes":[],"disable_action_mode":"fixed_minutes","time_disable_actions":null,"count_consecutive_errors":5,"detail_status":"thất bại","counts_toward_limit":true,"counts_toward_bad_target":true,"zalo_error_codes":[],"zalo_action_codes":[],"disable_action_days":null,"disable_action_time":null,"is_active":true,"is_delete":false}]$desired$::jsonb) AS d(error_type text, error_name text, error_desc text, error_code text, error_element text, noti_running_process text, noti_campaign text, update_status_account text, update_status_campaign text, disable_action_codes text[], time_disable_actions integer, count_consecutive_errors integer, is_active boolean, is_delete boolean, zalo_error_codes text[], detail_status text, counts_toward_limit boolean, counts_toward_bad_target boolean, update_login_status text, disable_action_mode text, zalo_action_codes text[], disable_action_days integer, disable_action_time time without time zone),unnest(d.disable_action_codes) a
